CREATE OR REPLACE VIEW v_kardex_completo AS SELECT ms.id_movimiento AS id_movimiento, ms.fecha AS fecha, p.nombre AS producto, m.descripcion AS medida, ms.tipo AS tipo, ms.cantidad AS cantidad, ms.observacion AS observacion, ms.usuario_registro AS usuario_registro, CONCAT(req.codigo,'-V',v.numero_viaje) AS codigo_viaje, req.codigo AS codigo_requerimiento, d.codigo AS codigo_despacho FROM movimientos_stock ms JOIN productos p ON ms.id_producto = p.id_producto JOIN medidas m ON p.id_medida = m.id_medida LEFT JOIN viajes v ON ms.id_viaje = v.id_viaje LEFT JOIN requerimientos req ON ms.id_requerimiento = req.id_requerimiento LEFT JOIN despachos d ON ms.id_despacho = d.id_despacho ORDER BY ms.fecha DESC;
